-- Catch-up: bring a database built from these migrations in line with the
-- live `school` project.
--
-- The initial schema was reconstructed from a dump that included tables,
-- foreign keys, RLS policies, functions and triggers, but not indexes or
-- unique constraints, and a later function was created directly in the
-- Supabase dashboard. A database replayed from this directory was therefore
-- missing 44 indexes (25 of them UNIQUE) and one function the app
-- calls, and carried one RLS policy the live project doesn't have. This
-- file closes those gaps. It was generated by comparing a replay of every
-- migration with the live database (names and definitions copied from it).
--
-- Safe to run anywhere:
--   * indexes use `if not exists`, so on the live project (where they all
--     already exist) they are no-ops;
--   * the function is `create or replace` with the live body;
--   * the policy drop uses `if exists`.
--
-- Not covered: the live `quiz_answers_attempt_id_question_id_key` unique
-- index. The repo already enforces the same rule through the
-- `quiz_answers_attempt_question_unique` constraint in the initial schema.

-- ----------------------------------------------------------------------------
-- 1. Unique indexes
--    The app upserts with `onConflict` column lists (grades, enrollments,
--    transport_trip_status, ...), which only work when a unique index on
--    exactly those columns exists. They also carry business rules the
--    server actions rely on: one active transport/hostel assignment per
--    student, no double-booked class/teacher/room timetable slot, unique
--    admission numbers, subject codes and payment references.
-- ----------------------------------------------------------------------------

create unique index if not exists curriculum_topics_unique_sequence
  on curriculum_topics (subject_id, education_level, level_number, term, sequence_order);

create unique index if not exists curriculum_topics_unique_week
  on curriculum_topics (subject_id, education_level, level_number, term, academic_year, week_number);

create unique index if not exists enrollments_student_id_class_id_academic_year_term_key
  on enrollments (student_id, class_id, academic_year, term);

create unique index if not exists enrollments_unique_student_term
  on enrollments (student_id, academic_year, term);

create unique index if not exists grades_assessment_id_student_id_key
  on grades (assessment_id, student_id);

create unique index if not exists guardian_links_unique_parent_student
  on guardian_links (parent_id, student_id);

create unique index if not exists hostel_assignments_one_active_per_student
  on hostel_assignments (student_id)
  where unassigned_at is null;

create unique index if not exists hostel_rooms_hostel_id_room_number_key
  on hostel_rooms (hostel_id, room_number);

create unique index if not exists invoices_student_id_fee_structure_id_key
  on invoices (student_id, fee_structure_id);

create unique index if not exists payments_reference_unique
  on payments (reference)
  where reference is not null;

create unique index if not exists profile_contacts_email_lower_idx
  on profile_contacts (lower(email));

create unique index if not exists quiz_attempts_quiz_id_student_id_key
  on quiz_attempts (quiz_id, student_id);

create unique index if not exists quiz_options_question_id_sequence_order_key
  on quiz_options (question_id, sequence_order);

create unique index if not exists quiz_questions_quiz_id_sequence_order_key
  on quiz_questions (quiz_id, sequence_order);

create unique index if not exists quizzes_assessment_id_key
  on quizzes (assessment_id);

create unique index if not exists route_vehicle_history_one_active_per_route
  on route_vehicle_history (route_id)
  where unassigned_at is null;

create unique index if not exists student_profiles_admission_no_key
  on student_profiles (admission_no);

create unique index if not exists subjects_code_key
  on subjects (code);

create unique index if not exists teacher_profiles_staff_id_key
  on teacher_profiles (staff_id);

create unique index if not exists transport_assignments_one_active_per_student
  on transport_assignments (student_id)
  where unassigned_at is null;

create unique index if not exists transport_stops_route_id_sequence_order_key
  on transport_stops (route_id, sequence_order);

create unique index if not exists transport_trip_status_route_id_trip_date_direction_key
  on transport_trip_status (route_id, trip_date, direction);

create unique index if not exists uq_timetable_class_slot
  on timetable_entries (class_id, weekday, period_number, academic_year, term);

create unique index if not exists uq_timetable_room_slot
  on timetable_entries (room, weekday, period_number, academic_year, term)
  where room is not null;

create unique index if not exists uq_timetable_teacher_slot
  on timetable_entries (teacher_id, weekday, period_number, academic_year, term);

-- ----------------------------------------------------------------------------
-- 2. Query-performance indexes
-- ----------------------------------------------------------------------------

create index if not exists idx_audit_log_actor
  on audit_log (actor_id, created_at desc);

create index if not exists idx_audit_log_entity
  on audit_log (entity_type, entity_id, created_at desc);

create index if not exists idx_classes_archived
  on classes (is_archived);

create index if not exists idx_classes_level
  on classes (education_level, level_number);

create index if not exists idx_curriculum_topics_scheme_lookup
  on curriculum_topics (subject_id, education_level, level_number, term, academic_year, week_number);

create index if not exists idx_grades_student
  on grades (student_id);

create index if not exists idx_invoices_status
  on invoices (status);

create index if not exists idx_invoices_student
  on invoices (student_id);

create index if not exists idx_lessons_homework_status
  on lessons (homework_status)
  where homework is not null;

create index if not exists idx_library_loans_book
  on library_loans (book_id);

create index if not exists idx_library_loans_outstanding
  on library_loans (due_at)
  where returned_at is null;

create index if not exists idx_library_loans_student
  on library_loans (student_id);

create index if not exists idx_notes_topic
  on topic_notes (topic_id);

create index if not exists idx_payments_invoice
  on payments (invoice_id);

create index if not exists idx_resources_topic
  on topic_resources (topic_id);

create index if not exists idx_subjects_level
  on subjects (education_level, min_level_number, max_level_number);

create index if not exists idx_timetable_class
  on timetable_entries (class_id, weekday);

create index if not exists idx_topics_subject_level_term
  on curriculum_topics (subject_id, education_level, level_number, term);

create index if not exists transport_locations_lookup_idx
  on transport_locations (route_id, trip_date, direction, recorded_at desc);

-- ----------------------------------------------------------------------------
-- 3. assign_student_to_route
--    Called by assignStudentToRoute() in lib/actions/transport.ts. Locks the
--    route row so concurrent assignments can't both pass the capacity check,
--    mirroring assign_student_to_hostel_room. SECURITY DEFINER with its own
--    admin / transport-officer check, so the default EXECUTE grants (which
--    match the live project) are correct.
-- ----------------------------------------------------------------------------

create or replace function public.assign_student_to_route(p_student_id uuid, p_route_id uuid, p_stop_id uuid, p_academic_year text)
 returns transport_assignments
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_route transport_routes%rowtype;
  v_capacity integer;
  v_current_riders integer;
  v_assignment transport_assignments%rowtype;
begin
  if not (is_admin() or is_transport_officer()) then
    raise exception 'Only an admin or the transport officer can do this.';
  end if;

  -- Lock the route row so two concurrent assignments to the same route
  -- can't both pass the capacity check before either commits — mirrors
  -- the "select ... for update" on hostel_rooms in
  -- assign_student_to_hostel_room.
  select * into v_route from transport_routes where id = p_route_id for update;
  if v_route.id is null then
    raise exception 'Route not found.';
  end if;

  if v_route.vehicle_id is not null then
    select capacity into v_capacity from vehicles where id = v_route.vehicle_id;

    -- Only enforced once a vehicle is actually assigned to the route — a
    -- route with no vehicle yet has no known capacity to check against,
    -- so assignment isn't blocked on that basis (just on the route
    -- existing at all). Matches the app's existing behavior.
    if v_capacity is not null then
      select count(*) into v_current_riders
        from transport_assignments
        where route_id = p_route_id and unassigned_at is null;

      if v_current_riders >= v_capacity then
        raise exception 'This route''s vehicle is already at seating capacity.';
      end if;
    end if;
  end if;

  if not exists (select 1 from transport_stops where id = p_stop_id and route_id = p_route_id) then
    raise exception 'That stop does not belong to this route.';
  end if;

  update transport_assignments set unassigned_at = now()
    where student_id = p_student_id and unassigned_at is null;

  insert into transport_assignments (student_id, route_id, stop_id, academic_year, assigned_by)
  values (p_student_id, p_route_id, p_stop_id, p_academic_year, auth.uid())
  returning * into v_assignment;

  return v_assignment;
end;
$function$;

-- ----------------------------------------------------------------------------
-- 4. transport_assignments write policy
--    The initial schema created `transport_assignments_write`, but the live
--    project doesn't have it: the only direct write the app makes
--    (unassignStudentFromRoute) uses the service-role client, which bypasses
--    RLS, and assignment goes through assign_student_to_route above. Leaving
--    the policy would let a database built from the repo accept direct
--    writes the live one rejects.
-- ----------------------------------------------------------------------------

drop policy if exists transport_assignments_write on transport_assignments;
